contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        address beforeOwner = c.owner();
        bool r1;
        try c.transferOwnership(newOwner) { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.owned() { r2 = false; } catch { r2 = true; }
        assert(r1 && r2 && c.owner() == beforeOwner);
    }
    receive() external payable {}
}
